PANELS = [('f', 'flow', '发布历史'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("Deployment app 把环境变量 V 依次改成 v1、v2、v3、v4:名下有 4 个 ReplicaSet——(revision 1, v1, replicas 0)、(2, v2, 0)、(3, v3, 0)、(4, v4, 2),旧的缩到 0 但都保留。kubectl rollout history 列出 REVISION 1~4,CHANGE-CAUSE 都是 <none>;--revision=2 能看到那一版的 Pod 模板(Image busybox:1.36、Environment V=v2)。", f=fl(F1, cur=[0, 1, 2]), t=tl(S(1), mark=lidx(S(1), '4 个版本之后的 ReplicaSet'), done=lidx(S(1), 'REVISION', '--revision=2')), kv=KV([['历史', '= Deployment 名下的 ReplicaSet'], ['revision', '记在 ReplicaSet 的注解里'], ['旧 ReplicaSet', 'replicas=0 但不删,为回滚用']], ['历史'])),
    step("kubectl rollout undo --to-revision=2:输出 rolled back;revision 2 的 ReplicaSet(后缀 667b7)被重新启用,revision 变成最新的 5(而不是新建一个),其余 1、3、4 保留,当前运行 v2。不带 --to-revision 再 undo 一次:回到上一个版本 v4(ReplicaSet cb5f7),它的 revision 变成 6。kubectl 还提示:用 kubectl apply 管理的 Deployment,undo 不会更新 last-applied 注解。", f=fl(F2, cur=[0, 1], mark=[2]), t=tl(S(2), mark=lidx(S(2), 'rolled back', '之后的 ReplicaSet'), done=lidx(S(2), '不带 --to-revision')), kv=KV([['undo', '不是倒退,而是把旧 ReplicaSet 重新当成最新一版'], ['revision 编号', '只增不减'], ['kubectl apply 管理的资源', 'undo 之后 last-applied 与实际不一致']], ['undo'])),
    step("revisionHistoryLimit: 2,改了 5 次(v1 到 v6)之后只剩 revision 4、5、6 三个 ReplicaSet(当前这个加最近 2 个旧的);想回滚到已经被删掉的 revision 1 → error: unable to find specified revision 1 in history。", f=fl(F3, cur=[1], mark=[2]), t=tl(S(3), mark=lidx(S(3), '想回滚到已经被删掉的 revision 1'), done=lidx(S(3), 'revisionHistoryLimit=2 改了 5 次')), kv=KV([['revisionHistoryLimit', '默认 10,超出就删最旧的 ReplicaSet'], ['设成 0', '不能回滚'], ['历史多了', 'ReplicaSet 对象也多,etcd 也要存']], ['revisionHistoryLimit'])),
    step("kubernetes.io/change-cause 注解写进 history 的 CHANGE-CAUSE 列(“初始版本 v1”“升级到 v2”)。kubectl rollout pause 之后连续改两次模板(V=v3 和加 EXTRA=1):ReplicaSet 仍是 2 个、Pod 没动;rollout resume 之后只多了 1 个 ReplicaSet(revision 3,v3),两次修改合成一次发布。", f=fl(F4, cur=[1, 2], done=[0]), t=tl(S(4), mark=lidx(S(4), 'rollout pause', 'rollout resume'), done=lidx(S(4), 'change-cause')), kv=KV([['change-cause', '注解,history 里显示,要自己写'], ['pause', '改模板不触发发布'], ['resume', '把暂停期间的改动合成一次']], ['pause'])),
]
A = mkartk('k46', 46, 'Kubernetes,Deployment,rollout history,rollout undo,revisionHistoryLimit,change-cause,真实验证,动画演示',
    '在 kind 集群里实测 Deployment 的发布历史:每个 Pod 模板版本对应一个 ReplicaSet(revision 记在注解里,旧的缩到 0 保留);rollout undo --to-revision=2 把 revision 2 的 ReplicaSet 重新启用并改号为 5,不带参数再 undo 回到 revision 4(变成 6);revisionHistoryLimit=2 时只保留当前加最近 2 个,回滚已被删除的 revision 报 unable to find specified revision;change-cause 注解显示在 history 里;pause/resume 把多次修改合成一次发布。',
    '`kubectl rollout history` 的历史存在哪?`rollout undo` 到底做了什么?revisionHistoryLimit 删掉历史后会怎样?这篇用 ReplicaSet 的 revision 注解把这几个问题都实测清楚。',
    [('revision 2 → 5', 'rollout undo --to-revision=2 之后,revision 2 的 ReplicaSet 被重新启用并改成的最新 revision 号'), ('3 个 ReplicaSet', 'revisionHistoryLimit=2、改了 5 次后保留的 ReplicaSet 数(当前 + 最近 2 个旧的)'), ('2 次修改 → 1 次发布', 'rollout pause 期间连改两次、resume 之后只产生的新 ReplicaSet 数')],
    [('历史就是 ReplicaSet', '<p>每改一次 Pod 模板,Deployment 就多一个 ReplicaSet,<code>deployment.kubernetes.io/revision</code> 注解记着它的版本号;旧的缩到 <code>replicas=0</code> 但保留。改了 4 次(v1 到 v4)后有 4 个 ReplicaSet,<code>kubectl rollout history</code> 列出 REVISION 1~4(CHANGE-CAUSE 都是 <code>&lt;none&gt;</code>),<code>--revision=2</code> 能看到那一版的模板内容。</p>'),
     ('undo 不是倒退', '<p><code>rollout undo --to-revision=2</code>:revision 2 的 ReplicaSet(后缀 667b7)被重新启用,编号改成最新的 5,而不是新建一个;1、3、4 保留。不带 <code>--to-revision</code> 再 undo 一次,回到“上一个版本”(v4,编号变成 6)。revision 号只增不减。注意 kubectl 的提示:如果 Deployment 是用 <code>kubectl apply</code> 管理的,undo 不会更新 <code>last-applied-configuration</code>,之后再 apply 旧 YAML 可能和实际不一致。</p>'),
     ('revisionHistoryLimit', '<p>默认保留 10 个旧版本。设成 2、改了 5 次之后,只剩 revision 4、5、6 三个 ReplicaSet(当前加最近 2 个旧的),更早的被删掉:<code>rollout undo --to-revision=1</code> 报 <code>unable to find specified revision 1 in history</code>。想回滚得多远,就把它设多大。</p>'),
     ('change-cause 与 pause', '<p>给 Deployment 加注解 <code>kubernetes.io/change-cause</code>,会显示在 <code>rollout history</code> 的 CHANGE-CAUSE 列(“初始版本 v1”“升级到 v2”),这是现在唯一能给历史写说明的办法。<code>rollout pause</code> 之后连续改两次模板,ReplicaSet 数量不变、Pod 不动;<code>rollout resume</code> 后只多了一个 ReplicaSet,把两次修改合成了一次发布。</p>')],
    steps,
    [ENV_K + '。三节点 kind 集群 kx-main(Kubernetes v1.37.0);Deployment app 2 个副本,busybox:1.36,环境变量 V 用来改变 Pod 模板(用 kubectl apply 修改);每次修改后等 updatedReplicas、readyReplicas、replicas 都等于 2 再继续;ReplicaSet 的版本取自注解 deployment.kubernetes.io/revision;每种情形各一次(ReplicaSet 名字后缀每次运行不同)',
     '没有验证:revisionHistoryLimit 为 0;回滚期间的 maxSurge 与 maxUnavailable;kubectl rollout status 的输出;Deployment 删除时 ReplicaSet 的级联(见垃圾回收一篇);对 StatefulSet、DaemonSet 的 rollout history(它们用的是 ControllerRevision 对象);kubectl set image 与 --record(已废弃)'],
    '发布历史', PANELS)
